begin;
select plan(12);
insert into public.bookmarks(id,url,url_key,title) values ('bbbbbbbb-9850-4000-8000-000000000001','https://example.com/resume','https://example.com/resume','Original');
insert into public.bookmark_jobs(id,kind,state,total,lease_token,lease_expires_at) values ('aaaaaaaa-9850-4000-8000-000000000001','check','processing',1,'cccccccc-9850-4000-8000-000000000001',now()+interval '90 seconds');
insert into public.bookmark_job_items(job_id,bookmark_id,expected_version,work) values ('aaaaaaaa-9850-4000-8000-000000000001','bbbbbbbb-9850-4000-8000-000000000001',1,'{"phase":"decision","observation":{"input":{"url":"https://example.com/resume","version":1}},"reservationId":"eeeeeeee-9850-4000-8000-000000000001"}');
insert into public.bookmark_ai_reservations(id,job_id,month,reserved_nano,input_tokens,state,health_evidence_key,health_bookmark_id) values ('eeeeeeee-9850-4000-8000-000000000001','aaaaaaaa-9850-4000-8000-000000000001',date_trunc('month',now() at time zone 'Asia/Seoul')::date,2752512,65536,'uncertain',repeat('d',64),'bbbbbbbb-9850-4000-8000-000000000001');
insert into public.bookmark_checks(bookmark_id,job_id,bookmark_version,status,reason,checked_url,evidence) values ('bbbbbbbb-9850-4000-8000-000000000001','aaaaaaaa-9850-4000-8000-000000000001',1,'healthy','provisional','https://example.com/resume','{}');
set local role authenticated;
select set_config('request.jwt.claim.sub','480f5282-7933-4800-a970-d6bc8f05e8cb',true);
select lives_ok($$select public.bookmark_command('edit','{"id":"bbbbbbbb-9850-4000-8000-000000000001","version":1,"title":"Edited"}')$$,'owner edits while health observation is in flight');
reset role;
select ok(public.bookmark_worker_commit('aaaaaaaa-9850-4000-8000-000000000001','cccccccc-9850-4000-8000-000000000001','{"items":[{"id":"bbbbbbbb-9850-4000-8000-000000000001","version":1,"state":"done"}]}'),'stale publication closes its item');
select is((select state from public.bookmark_jobs where id='aaaaaaaa-9850-4000-8000-000000000001'),'failed','changed bookmark is not published as completed');
set local role authenticated;
select lives_ok($$select public.bookmark_command('resume','{"id":"aaaaaaaa-9850-4000-8000-000000000001"}')$$,'owner resumes the failed job');
reset role;
select is((select expected_version from public.bookmark_job_items where job_id='aaaaaaaa-9850-4000-8000-000000000001'),2,'resume adopts current version');
select is((select work from public.bookmark_job_items where job_id='aaaaaaaa-9850-4000-8000-000000000001'),null::jsonb,'resume clears the stale observation and phase');
select is((select state from public.bookmark_ai_reservations where id='eeeeeeee-9850-4000-8000-000000000001'),'uncertain','resume retains the uncertain receipt');
update public.bookmark_jobs set state='paused' where id<>'aaaaaaaa-9850-4000-8000-000000000001';
select is(public.bookmark_worker_claim()->'items'->0->'work','null'::jsonb,'worker receives a fresh page checkpoint after resume');
select ok(public.bookmark_worker_commit('aaaaaaaa-9850-4000-8000-000000000001',(select lease_token from public.bookmark_jobs where id='aaaaaaaa-9850-4000-8000-000000000001'),jsonb_build_object('items',jsonb_build_array(jsonb_build_object('id','bbbbbbbb-9850-4000-8000-000000000001','version',2,'state','done','work',null,'check',jsonb_build_object('status','healthy','reason','HTTP 200','checkedUrl','https://example.com/resume','evidence',jsonb_build_object('observedAt',now()+interval '1 second','content',jsonb_build_object('title',repeat('t',300),'excerpt',repeat('e',200)),'media',jsonb_build_object('items',(select jsonb_agg(jsonb_build_object('kind','image','label',repeat('x',80),'urlHash',lpad(to_hex(i),64,'0'),'state','reachable','httpStatus',200,'reasonCode','MEDIA_SEMANTICS_UNVERIFIED')) from generate_series(1,20) i)))))))),'maximum compacted media evidence commits through the real RPC');
select is((select bookmark_version from public.bookmark_checks where job_id='aaaaaaaa-9850-4000-8000-000000000001'),2,'updated evidence belongs to the resumed current version');
select ok((select octet_length(evidence::text)<=8192 from public.bookmark_checks where job_id='aaaaaaaa-9850-4000-8000-000000000001'),'persisted evidence obeys the actual PostgreSQL byte limit');
select is((select state from public.bookmark_jobs where id='aaaaaaaa-9850-4000-8000-000000000001'),'succeeded','fresh observation completes resumed job');
select * from finish(); rollback;
